using Renderer = std::variant<HtmlView, JsonView, CsvView>;
std::map<std::string, Renderer> views{{"text/html", HtmlView{}}, {"application/json", JsonView{}}};
void serve(const Model &m, const std::string &accept, std::ostream &out) {
    auto it = views.find(best_match(accept));
    if (it == views.end()) throw NotAcceptable{};          // explicit 406 path
    std::visit([&](const auto &v) { v.render(m, out); }, it->second);
}

